#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>

using namespace std;
int main() {
    // 处理输入
    int money;
    cin >> money;
    cin.ignore();

    string line;
    getline(cin, line);
    istringstream iss(line);
    vector<int> topup_info;
    int value;

    while (iss >> value) {
        topup_info.push_back(value);
    }

    vector<int> dp(money + 1, 0);

    for (size_t i = 0; i < topup_info.size(); i++) {
        for (int j = static_cast<int>(i) + 1; j <= money; j++) {
            dp[j] = max(dp[j], dp[j - (i + 1)] + topup_info[i]);
        }
    }
    cout << dp[money] << endl;

    return 0;
}


