#include <stdio.h>
#include <string.h>
#include <stdlib.h>


int main() {
    int money;

    scanf("%d", &money);

    // 定义售价表数组，并读取售价表
    int topupInfo[100];
    int n = 0;
    while (scanf("%d", &topupInfo[n]) != EOF) {
        n++;
    }

    int dp[1001] = {0};

    // 遍历每一个充值选项
    for (int i = 0; i < n; i++) {
        // 从当前预算开始，向后更新 dp 数组
        for (int j = i + 1; j <= money; j++) {
            // 更新 dp[j] 为在充值 i+1 元的情况下获得的最大短信数
            dp[j] = dp[j] > dp[j - (i + 1)] + topupInfo[i] ? dp[j] : dp[j - (i + 1)] + topupInfo[i];
        }
    }

    // 输出在预算 money 下最多可获得的短信条数
    printf("%d\n", dp[money]);

    return 0;
}
